def solve(line: str):
    fields = []
    current = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                # check for escaped quote
                if i + 1 < n and line[i+1] == '"':
                    current.append('"')
                    i += 1  # skip next quote
                else:
                    in_quotes = False
            else:
                current.append(c)
        else:
            if c == ',':
                fields.append(''.join(current))
                current = []
            elif c == '"':
                in_quotes = True
            else:
                current.append(c)
        i += 1
    # Append last field
    fields.append(''.join(current))
    # Special case: empty input returns [''] (already does)
    return fields

