def solve(coins, amount):
    """Fewest coins summing to amount (unlimited supply of each coin), or -1."""
    if amount == 0:
        return 0
    if amount < 0:
        return -1
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
