def solve(weights, values, capacity):
    """0/1 knapsack returning maximum total value.
    Handles edge cases such as negative capacity or mismatched input lengths.
    """
    # Edge cases
    if capacity <= 0 or not weights:
        return 0
    # Ensure weights and values have same length; truncate to min length
    n = min(len(weights), len(values))
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # Skip items with non‑positive weight (zero weight would cause infinite addition)
        if w <= 0:
            # For zero weight, we can take it once without affecting capacity
            # Add its value to all dp entries if beneficial
            if v > 0:
                for c in range(capacity + 1):
                    dp[c] += v
            continue
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

