def solve(n):
    """Return the number of prime numbers strictly less than *n*.
    The function tolerates non‑integer inputs by converting them to ``int`` if possible;
    otherwise it returns ``0``. For ``n`` ≤ 2 the answer is ``0``.
    """
    # Defensive conversion
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Sieve of Eratosthenes using a bytearray for memory efficiency.
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if sieve[p]:
            start = p * p
            step = p
            # slice assignment works even if start >= n (produces empty slice)
            sieve[start:n:step] = b'\x00' * ((n - 1 - start) // step + 1) if start < n else b''
    return sum(sieve)

