def solve(matrix):
    """Return determinant of integer matrix using Bareiss algorithm.
    Empty matrix has determinant 1.
    """
    # Handle empty matrix
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a mutable copy
    A = [list(map(int, row)) for row in matrix]
    sign = 1
    # Bareiss fraction-free elimination
    for k in range(n - 1):
        # Pivot handling: if zero, swap with a lower row
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            sign = -sign
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Compute the new element using integer arithmetic
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0  # elements below pivot become zero
    return sign * A[n - 1][n - 1]

