def solve(weights, values, capacity):
    """0/1 knapsack: maximum total value with given capacity.
    Assumes weights and values are lists of equal length. Items with weight
    greater than capacity are skipped. Uses classic DP with O(capacity) space.
    """
    if capacity <= 0:
        return 0
    n = min(len(weights), len(values))
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w <= 0:
            # Zero or negative weight: treat as weight 0 but only add value once
            # Update all capacities in place (no infinite loop because each item only once)
            for c in range(capacity, -1, -1):
                if dp[c] + v > dp[c]:
                    dp[c] = dp[c] + v
            continue
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

