        return 0
    # Ensure weights and values are iterable of numbers
    w_list = list(weights) if weights is not None else []
    v_list = list(values) if values is not None else []
    n = min(len(w_list), len(v_list))
    dp = [0] * (capacity + 1)
    for i in range(n):
        # Coerce weight and value to int
        try:
            w = int(w_list[i])
            v = int(v_list[i])
        except Exception:
            continue
        if w <= 0:
            # Zero or negative weight: add its value once to all capacities if beneficial
            if v > 0:
                for c in range(capacity + 1):
