def solve(word1, word2):
    """Minimum number of insertions/deletions/substitutions to turn word1
    into word2 (Levenshtein edit distance)."""
    m, n = len(word1), len(word2)
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        c = word1[i - 1]
        for j in range(1, n + 1):
            if c == word2[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j - 1], prev[j], cur[j - 1])
        prev = cur
    return prev[n]

def solve(n, b):
    """Write integer n in base b (2..36) with digits 0-9 then a-z.

    Negative n gets a leading minus sign.
    """
    if b < 2 or b > 36:
        raise ValueError('base out of range')
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n == 0:
        return '0'
    neg = n < 0
    n = abs(n)
    out = []
    while n:
        out.append(digits[n % b])
        n //= b
    if neg:
        out.append('-')
    return ''.join(reversed(out))

