def solve(coins, amount):
    """Return the minimum number of coins needed to make up amount using unlimited coins.
    If impossible, return -1.
    DP approach O(amount * len(coins))."""
    # Edge case
    if amount == 0:
        return 0
    # Initialize DP array with amount+1 (inf)
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non-positive coin values
        for x in range(coin, amount + 1):
