def solve(n, b):
    """Convert integer n to its representation in base b (2 <= b <= 36).
    Uses digits 0-9 then a-z for values 10-35. Negative numbers have a leading '-'.
    """
    if not (2 <= b <= 36):
        raise ValueError('Base must be between 2 and 36')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n:
