def solve(weights, values, capacity):
    """0/1 knapsack: return the maximum total value of items that fit within capacity.
    Uses a 1‑dimensional DP array. The answer is the maximum value achievable for any
    weight up to *capacity* (not necessarily exactly *capacity*)."""
    n = len(weights)
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate backwards to avoid reusing the same item
        for cap in range(capacity, w - 1, -1):
            new_val = dp[cap - w] + v
            if new_val > dp[cap]:
                dp[cap] = new_val
    return max(dp)

